import { zipObject, fill } from 'lodash-es';
import { State, type MixinFactory } from '@stencil/core';
import type { VisibilityOptions, VisibilityState } from '@byted-keystone/table';
import { getHiddenColumnKeys } from '../helpers';
import type { TableFeatureArgs } from '../types';

export const VisibilityFactory = (Base: ReturnType<MixinFactory>) => {
  class TableVisibility extends Base {
    @State() internalVisibilityState: VisibilityState = {};

    constructor() {
      super();
    }

    getVisibilityState = (): VisibilityState => this.internalVisibilityState;

    setInitialVisibilityState = ({ columns }: TableFeatureArgs) => {
      const hiddenColumnKeys = getHiddenColumnKeys(columns);
      const initialVisibilityState: VisibilityState = zipObject(
        hiddenColumnKeys,
        fill(Array(hiddenColumnKeys.length), false),
      );

      this.internalVisibilityState = initialVisibilityState;
    };

    getVisibilityFeatureOptions = ({ columns }: TableFeatureArgs): VisibilityOptions => {
      const hiddenColumnKeys = getHiddenColumnKeys(columns);

      return {
        enableHiding: hiddenColumnKeys.length > 0,
      };
    };
  }
  return TableVisibility;
};
