import { Fragment, h, type FunctionalComponent } from '@stencil/core';
import { SELECTION_COLUMN_ID, TOGGLER_COLUMN_ID, renderBodyCell } from '../helpers';
import { TableSelectionCheckbox } from './table-selection-checkbox';
import type { JSXBase } from '@stencil/core/internal';
import type { VirtualItem } from '@tanstack/virtual-core';
import type { Row, RowData, Cell, Column } from '@byted-keystone/table';
import { KsIconFilledChevronRight } from '@fe-infra/keystone-icons-stencil';
import { isEventFromTopLayerSurface } from '@src/shared/dom';
import type { TableCellSkeletonConfig } from '../types';

interface ITableBodyRowProps<TData> extends JSXBase.HTMLAttributes<HTMLTableRowElement> {
  prefix: string;
  row: Row<TData>;
  rowAlign: 'start' | 'center';
  loading?: boolean;
  virtualItems?: VirtualItem[];
  visibleColumns?: Column<TData, unknown>[];
  hideToggler?: boolean;
  hideSelection?: boolean;
  isLastPinned?: boolean;
  isLastBodyRow?: boolean;
  contentPartName?: string | ((value: unknown, cell: Cell<TData, unknown>) => string);
  cellPartName?: string | ((value: unknown, cell: Cell<TData, unknown>) => string);
  cellSkeletonContent?: (cell: Cell<TData, unknown>) => TableCellSkeletonConfig | undefined;
  onRowClick?: (row: Row<TData>) => void;
  onRowHover?: (row: Row<TData>) => void;
  onRowHoverEnd?: (row: Row<TData>) => void;
  onCellPointerEnter?: (cell: Cell<TData, unknown>) => void;
  onCellPointerLeave?: (cell: Cell<TData, unknown>) => void;
  measureRef?: (el: HTMLTableRowElement | undefined) => void;
  slotKey: (instance: Cell<TData, unknown>) => string;
}

const renderSkeletonFallback = ({
  prefix,
  align,
  config,
}: {
  prefix: string;
  align?: 'start' | 'center' | 'end';
  config?: TableCellSkeletonConfig;
}) => {
  const skeletonAlignClass = align ? `${prefix}__skeleton--align-${align}` : undefined;
  const style = config?.style;
  const content = config?.content;
  const hasProfile = config?.type === 'profile';
  const hasContent = content !== undefined;

  if (hasProfile || hasContent) {
    return (
      <Fragment>
        {hasProfile && <div class={`${prefix}__skeleton-profile animate-pulse`} />}
        <div
          class={{
            [`${prefix}__skeleton`]: true,
            [`${prefix}__skeleton--text`]: true,
            [skeletonAlignClass ?? '']: Boolean(skeletonAlignClass),
          }}
          style={style}
        >
          {content}
        </div>
      </Fragment>
    );
  }

  return (
    <div
      class={{
        [`${prefix}__skeleton`]: true,
        ['animate-pulse']: true,
        [skeletonAlignClass ?? '']: Boolean(skeletonAlignClass),
      }}
      style={style}
    />
  );
};

// eslint-disable-next-line max-lines-per-function
export const TableBodyRow = <TData extends RowData>(props: ITableBodyRowProps<TData>): FunctionalComponent | null => {
  const {
    prefix,
    row,
    rowAlign,
    loading,
    virtualItems,
    visibleColumns,
    hideToggler,
    hideSelection,
    isLastPinned,
    isLastBodyRow,
    contentPartName,
    cellPartName,
    cellSkeletonContent,
    onRowClick,
    onRowHover,
    onRowHoverEnd,
    onCellPointerEnter,
    onCellPointerLeave,
    measureRef,
    slotKey,
    ...restProps
  } = props;

  if (row.getParentRow() && !row.getParentRow()?.getIsExpanded()) {
    return null;
  }

  const renderExpandToggler = () => (
    <ks-icon-button
      size="xs"
      variant="text"
      onClick={row.getToggleExpandedHandler()}
      data-testid="components-table-body-row-tUbmxd"
    >
      <KsIconFilledChevronRight
        class={{
          [`${prefix}__expand-icon`]: true,
          [`${prefix}__expand-icon--expanded`]: row.getIsExpanded(),
        }}
        size="14"
      />
    </ks-icon-button>
  );

  // const visibleCells = row.getVisibleCells();
  // const renderCells = virtualItems
  //   ? virtualItems.map((item) => visibleCells[item.index]).filter((cell) => cell !== undefined)
  //   : visibleCells;

  const renderCells = virtualItems
    ? row.getVisibleCells(virtualItems.map((item) => item.index))
    : row.getVisibleCells();
  const firstCenterCellIndex = virtualItems ? renderCells.findIndex((cell) => !cell.column.getIsPinned()) : -1;
  const lastCenterCellIndex = virtualItems
    ? renderCells.reduce((lastIndex, cell, index) => (!cell.column.getIsPinned() ? index : lastIndex), -1)
    : -1;

  const lastLeftPinnedIndex = renderCells.find((c) => c.column.getIsLastColumn('left'))?.column.getIndex() ?? -1;
  const firstRightPinnedIndex = renderCells.find((c) => c.column.getIsFirstColumn('right'))?.column.getIndex() ?? -1;

  const handleCellPointerEnter = (e: Event) => {
    if (!onCellPointerEnter) return;
    const index = Number((e.currentTarget as HTMLElement).dataset['index']);
    const cell = renderCells[index];
    if (cell) onCellPointerEnter(cell);
  };

  const handleCellPointerLeave = (e: Event) => {
    if (!onCellPointerLeave) return;
    const index = Number((e.currentTarget as HTMLElement).dataset['index']);
    const cell = renderCells[index];
    if (cell) onCellPointerLeave(cell);
  };

  function handleSelectionChange(checked: boolean) {
    row.toggleSelected(checked);
  }

  const onClick = (e: Event) => {
    if (isEventFromTopLayerSurface(e, e.currentTarget)) {
      return;
    }

    onRowClick?.(row);
  };

  const canSelect = row.getCanSelect?.() ?? true;

  return (
    <tr
      class={{
        [`${prefix}__tbody-row`]: true,
        [`${prefix}__tbody-row--selected`]: row.getIsSelected(),
        [`${prefix}__tbody-row--disabled`]: !canSelect,
        [`${prefix}__tbody-row--pinned`]: Boolean(row.getIsPinned()),
        [`${prefix}__tbody-row--can-expand`]: row.getCanExpand(),
        [`${prefix}__tbody-row--has-parent`]: Boolean(row.getParentRow()),
        [`${prefix}__tbody-row--last`]: Boolean(isLastBodyRow),
      }}
      ref={measureRef}
      onClick={onClick}
      onPointerEnter={() => onRowHover?.(row)}
      onPointerLeave={() => onRowHoverEnd?.(row)}
      {...restProps}
      data-testid="components-table-body-row-oJYYei"
    >
      {renderCells.map((cell, index) => {
        const columnSpan =
          typeof cell.column.columnDef.meta?.colSpan === 'function'
            ? cell.column.columnDef.meta.colSpan(row, row.index)
            : cell.column.columnDef.meta?.colSpan;

        // Set colSpan to 0 on the element will won't work, so we need to return null here.
        if (columnSpan === 0) return null;

        const effectiveSpan = columnSpan ?? 1;
        const columnAlign = cell.column.columnDef.meta?.align;
        const columnPinningPosition = cell.column.getIsPinned();
        const isLastLeftPinnedColumn =
          columnPinningPosition === 'left' &&
          lastLeftPinnedIndex !== -1 &&
          cell.column.getIndex() <= lastLeftPinnedIndex &&
          lastLeftPinnedIndex < cell.column.getIndex() + effectiveSpan;
        const isFirstRightPinnedColumn =
          columnPinningPosition === 'right' &&
          firstRightPinnedIndex !== -1 &&
          cell.column.getIndex() <= firstRightPinnedIndex &&
          firstRightPinnedIndex < cell.column.getIndex() + effectiveSpan;

        let widthStyle = virtualItems ? `calc(var(--ks-comp-width-table-column-${cell.column.id}) * 1px)` : undefined;

        if (virtualItems && columnSpan !== undefined && columnSpan > 1 && visibleColumns) {
          const currentIndex = visibleColumns.findIndex((c) => c.id === cell.column.id);
          if (currentIndex !== -1) {
            const spannedColumns = visibleColumns.slice(currentIndex, currentIndex + columnSpan);
            if (spannedColumns.length > 0) {
              const sumVar = spannedColumns.map((c) => `var(--ks-comp-width-table-column-${c.id})`).join(' + ');
              widthStyle = `calc((${sumVar}) * 1px)`;
            }
          }
        }

        const skeletonFallback = renderSkeletonFallback({
          prefix,
          align: columnAlign,
          config: cellSkeletonContent?.(cell),
        });

        return (
          <td
            key={cell.id}
            colSpan={columnSpan}
            data-index={index}
            class={{
              [`${prefix}__cell`]: true,
              [`${prefix}__cell--align-${columnAlign}`]: Boolean(columnAlign),
              [`${prefix}__cell--pinned`]: Boolean(columnPinningPosition),
              [`${prefix}__cell--last-pinned`]: Boolean(isLastPinned),
              [`${prefix}__cell--start-shadow`]: isFirstRightPinnedColumn,
              [`${prefix}__cell--end-shadow`]: isLastLeftPinnedColumn,
              [`${prefix}__tbody-cell`]: true,
            }}
            style={{
              width: widthStyle,
              marginInlineStart:
                index === firstCenterCellIndex ? 'var(--ks-comp-table-virtual-padding-start)' : undefined,
              marginInlineEnd: index === lastCenterCellIndex ? 'var(--ks-comp-table-virtual-padding-end)' : undefined,
              insetInlineStart: columnPinningPosition === 'left' ? `${cell.column.getStart('left')}px` : undefined,
              insetInlineEnd: columnPinningPosition === 'right' ? `${cell.column.getAfter('right')}px` : undefined,
            }}
            part={typeof cellPartName === 'function' ? cellPartName(cell.getValue(), cell) : cellPartName}
            // eslint-disable-next-line react/jsx-no-bind
            onPointerEnter={handleCellPointerEnter}
            // eslint-disable-next-line react/jsx-no-bind
            onPointerLeave={handleCellPointerLeave}
            data-testid={`components-table-body-row-7CxkFg-${cell.id}`}
          >
            <div
              class={{
                [`${prefix}__cell-content`]: true,
                [`${prefix}__cell-content--align-${rowAlign}`]: true,
              }}
              part={typeof contentPartName === 'function' ? contentPartName(cell.getValue(), cell) : contentPartName}
              style={
                cell.column.id === TOGGLER_COLUMN_ID
                  ? {
                      paddingLeft: '0',
                      paddingRight: '0',
                    }
                  : undefined
              }
            >
              {cell.column.id === SELECTION_COLUMN_ID &&
                (loading ? (
                  <div class={`${prefix}__skeleton--selection animate-pulse`} />
                ) : (
                  !hideSelection && (
                    <TableSelectionCheckbox
                      checked={row.getIsSelected()}
                      indeterminate={row.getIsSomeSelected()}
                      disabled={!row.getCanSelect()}
                      onChange={handleSelectionChange}
                      aria-label="Select row"
                      data-testid="components-table-body-row-fAuWW4"
                    />
                  )
                ))}
              {cell.column.id === TOGGLER_COLUMN_ID && !hideToggler && row.getCanExpand() && renderExpandToggler()}
              {cell.column.id !== SELECTION_COLUMN_ID &&
                cell.column.id !== TOGGLER_COLUMN_ID &&
                (loading && cell.getValue() === undefined ? (
                  <div class={`${prefix}__skeleton animate-pulse`} />
                ) : (
                  renderBodyCell(cell.column.columnDef.cell, cell.getContext(), slotKey, skeletonFallback)
                ))}
            </div>
          </td>
        );
      })}
    </tr>
  );
};
