import {
  Watch,
  Prop,
  Event,
  Mixin,
  forceUpdate,
  Element,
  type EventEmitter,
  type ComponentInterface,
  Method,
} from '@stencil/core';
import { isEqual, merge } from 'lodash-es';
import {
  PaginationFactory,
  ReorderFactory,
  ExpandableFactory,
  ResizingFactory,
  VisibilityFactory,
  SortingFactory,
  SelectionFactory,
  PinningFactory,
} from '../features';
import {
  createTableInstance,
  getTableColumnDefs,
  PercentageWidthObserver,
  resolveResponsiveColumnWidths,
  SELECTION_COLUMN_ID,
  TOGGLER_COLUMN_ID,
  type CreateTableInstanceProps,
} from '../helpers';
import type { Options } from 'sortablejs';
import {
  type Table,
  type TableState,
  type RowData,
  type Row,
  type Column,
  type Cell,
  type SortDirection,
} from '@byted-keystone/table';
import type { DetailArgs } from '@src/shared/dom';
import type {
  TableColumn,
  TableColumnGroup,
  TableSortingConfig,
  TableExpandableConfig,
  TableRowPinningConfig,
  TableRowSelectionConfig,
  TableCellSkeletonConfig,
  TableFeatureArgs,
  TableScrollPosition,
  TableScrollToPositionOptions,
} from '../types';

export abstract class TableCore
  extends Mixin(
    PaginationFactory,
    ReorderFactory,
    ExpandableFactory,
    ResizingFactory,
    VisibilityFactory,
    SortingFactory,
    SelectionFactory,
    PinningFactory,
  )
  implements ComponentInterface
{
  protected table!: Table<RowData>;
  @Element() el!: HTMLKsTableElement;

  /** Data items to render in the table body. */
  @Prop() dataSource: RowData[] = [];
  @Watch('dataSource')
  protected dataSourceChanged(dataSource: RowData[]) {
    this.table?.setOptions((prev) => ({
      ...prev,
      data: dataSource,
    }));
  }
  /** Column definitions, including headers, cells and optional footers. */
  @Prop() columns: (TableColumn | TableColumnGroup)[] = [];
  @Watch('columns')
  protected columnsChanged(columns: (TableColumn | TableColumnGroup)[]) {
    const options = this.getTableOptions();
    const columnDefs = getTableColumnDefs({
      columns,
      options,
      rowSelection: this.rowSelection,
      expandable: this.expandable,
    });
    this.setInitialColumnOrderState(this.tableFeatureArgs);
    this.setInitialColumnPinningState(this.tableFeatureArgs);
    this.shouldApplyResolvedColumnSizes = true;
    this.table?.setOptions((prev) => ({
      ...prev,
      ...options,
      state: {
        ...prev.state,
        ...this.getTableState(),
      },
      columns: columnDefs,
    }));
  }
  /** Unique key generator for each row. Accepts a function that returns the row key. */
  @Prop() rowKey?: (originalRow: RowData, index: number, parent?: Row<RowData>) => string;
  /** Whether to enable manual mode. */
  @Prop() manual = false;
  /** Custom config rendered inside the dynamic body cell skeleton fallback. */
  @Prop() cellSkeletonContent?: (cell: Cell<RowData, unknown>) => TableCellSkeletonConfig | undefined;

  @Watch('rowPinning')
  protected rowPinningChanged({ top }: TableRowPinningConfig, old: TableRowPinningConfig) {
    if (isEqual(top, old.top)) return;

    this.internalRowPinningState = { top };
    this.updateTableOptions();
  }

  @Watch('sorting')
  protected sortingChanged(sorting: TableSortingConfig) {
    if (!this.manual) this.internalSortingState = sorting;
    this.updateTableOptions();
  }

  @Watch('pagination')
  protected paginationChanged() {
    const options = this.getTableOptions();
    this.table?.setOptions((prev) => ({
      ...prev,
      ...options,
      state: {
        ...prev.state,
        ...this.getTableState(),
      },
    }));
  }

  // Note: In Stencil, when watching an object property, the `@Watch` decorator on a base class does not work; it must be placed in the component class
  protected rowSelectionChanged({ selectedRowKeys = [] }: TableRowSelectionConfig) {
    if (!this.manual) this.internalRowSelectionState = this.assembleRowSelectionState(selectedRowKeys);
    this.updateTableOptions();
  }

  // Same as `rowSelectionChanged` above, but for the `expandable` property
  protected expandableChanged({ expandedRowKeys = [] }: TableExpandableConfig) {
    if (!this.manual) this.internalExpandedState = this.assembleExpandedState(expandedRowKeys);
    this.updateTableOptions();
  }

  /** Emitted when the internal table state updates. */
  @Event({ bubbles: false, composed: false }) ksStateChange!: EventEmitter<TableState>;
  /** Custom event triggered when an action is clicked. */
  @Event({ bubbles: false, composed: false }) ksAction!: EventEmitter<DetailArgs<[string, Column<RowData, unknown>]>>;
  /** Custom event triggered when a row is clicked. */
  @Event({ bubbles: false, composed: false }) ksRowClick!: EventEmitter<unknown>;
  /** Custom event triggered when a row is hovered. */
  @Event({ bubbles: false, composed: false }) ksRowHover!: EventEmitter<unknown>;
  /** Custom event triggered when a row is no longer hovered. */
  @Event({ bubbles: false, composed: false }) ksRowHoverEnd!: EventEmitter<unknown>;
  /** Custom event triggered when a cell is hovered. */
  @Event({ bubbles: false, composed: false }) ksCellPointerEnter!: EventEmitter<{
    row: Row<RowData>;
    column: Column<RowData, unknown>;
    cell: Cell<RowData, unknown>;
  }>;
  /** Custom event triggered when a cell is no longer hovered. */
  @Event({ bubbles: false, composed: false }) ksCellPointerLeave!: EventEmitter<{
    row: Row<RowData>;
    column: Column<RowData, unknown>;
    cell: Cell<RowData, unknown>;
  }>;
  /** Custom event triggered when a sorter is clicked. */
  @Event({ bubbles: false, composed: false }) ksSorterClick!: EventEmitter<{
    id: unknown;
    direction: false | SortDirection;
  }>;
  /** Custom event triggered when the table scroll position changes. */
  @Event({ bubbles: false, composed: false }) ksScrollPositionChange!: EventEmitter<TableScrollPosition>;
  /** [Perf]: emitted in `componentDidRender` function */
  @Event({ bubbles: false, composed: false }) ksSkeletonRenderFinish!: EventEmitter<number>;
  private ksSkeletonRenderStart: null | number = null;
  /**
   * @private Called by hydration layer, please do not use
   */
  @Method()
  onDynamicChildrenFilled() {
    if (this.ksSkeletonRenderStart !== null) {
      this.ksSkeletonRenderFinish.emit(performance.now() - this.ksSkeletonRenderStart);
      this.ksSkeletonRenderStart = null;
    }
  }

  /** Scrolls the table wrapper to the provided top and left positions. */
  @Method()
  scrollToPosition(options?: TableScrollToPositionOptions) {
    this.scrollToTablePosition(options);
  }

  constructor() {
    super();
  }

  componentWillLoad(): Promise<void> | void {
    this.setInitialTableState();
    this.initializeTable();
  }

  connectedCallback(): void {
    if (!this.hasLoaded) {
      return;
    }

    this.ensurePercentageWidthObserver();
    this.percentageWidthObserver?.start();
    this.percentageWidthObserver?.sync();
  }

  componentDidLoad(): void {
    requestAnimationFrame(() => {
      // [For Virtual Table] We need to wait after the table rerendered then reset the pinned rows.
      this.initializePinnedRows();
    });
    this.ensurePercentageWidthObserver();
    this.percentageWidthObserver?.start();
    this.percentageWidthObserver?.sync();
    this.hasLoaded = true;
  }
  private percentageWidthObserver?: PercentageWidthObserver;
  private lastResolvedColumnSizes: Record<string, number> = {};
  private shouldApplyResolvedColumnSizes = false;
  protected hasLoaded = false;

  conductColumnsAutoWidth(): void {
    const options = this.getTableOptions();
    const columnDefs = getTableColumnDefs({
      columns: this.columns,
      options,
      rowSelection: this.rowSelection,
      expandable: this.expandable,
    });

    const totalWidth = this.getWidthReferenceElement().clientWidth;
    if (!totalWidth) {
      return;
    }

    const {
      resolvedColumnSizes: nextResolvedColumnSizes,
      resolvedPercentageWidth,
      shouldDistributeRemainingWidth,
    } = resolveResponsiveColumnWidths({
      columnDefs,
      columns: this.columns,
      manualColumnSizes: this.getColumnSizingState(this.manual),
      totalWidth,
    });

    if (!resolvedPercentageWidth && !shouldDistributeRemainingWidth && isEqual(this.lastResolvedColumnSizes, {})) {
      return;
    }

    if (!this.shouldApplyResolvedColumnSizes && isEqual(this.lastResolvedColumnSizes, nextResolvedColumnSizes)) {
      return;
    }

    this.lastResolvedColumnSizes = nextResolvedColumnSizes;
    this.shouldApplyResolvedColumnSizes = false;
    this.table.setOptions((prev) => ({
      ...prev,
      ...options,
      state: {
        ...prev.state,
        ...this.getTableState(),
      },
      columns: columnDefs,
    }));
    this.onResponsiveColumnWidthsChanged();
    forceUpdate(this);
  }

  componentDidRender(): void {
    this.initializePinnedRows();
    this.conductColumnsAutoWidth();
    this.ksSkeletonRenderStart = performance.now();
  }

  disconnectedCallback(): void {
    this.percentageWidthObserver?.stop();
    this.sortable?.destroy();
    this.sortable = undefined;
  }

  override initializeSortable(el: HTMLElement, options: Options): void {
    let savedOrder: string[] = [];

    super.initializeSortable(el, {
      ...options,
      onStart: (evt) => {
        savedOrder = [...this.table.getState().columnOrder];
        let { oldIndex } = evt as { oldIndex: number };
        const leftPinnedCount = this.table.getLeftVisibleLeafColumns().length;
        if (this.columnVirtualizer) {
          const indexes = this.columnVirtualizer.getVirtualIndexes();
          // * Adjust the index to account for left pinned columns
          // * Virtualizer: The index is only for center columns, so we need to add the left pinned count to get the actual index.
          // * Sortable / savedOrder: The index is for all columns.
          // * [Node] Usually this is unnecessary, since the virtual indexes should be in continuous order, but it's better to be safe.
          // eslint-disable-next-line @typescript-eslint/no-non-null-assertion
          oldIndex = indexes[oldIndex - leftPinnedCount]! + leftPinnedCount;
        }
        this.currentDragging = savedOrder[oldIndex] || null;
        options.onStart?.(evt);
      },
      onEnd: (evt) => {
        /* istanbul ignore next */
        if (evt.oldIndex === undefined || evt.newIndex === undefined) return;
        const leftPinnedCount = this.table.getLeftVisibleLeafColumns().length;
        const lastLeftPinnedColumnIndex = leftPinnedCount - 1;
        const firstRightPinnedColumnIndex = leftPinnedCount + this.table.getCenterVisibleLeafColumns().length;
        if (evt.newIndex <= lastLeftPinnedColumnIndex || evt.newIndex >= firstRightPinnedColumnIndex) {
          this.sortable?.sort(savedOrder, true);
          return;
        }
        let { oldIndex, newIndex } = evt;
        if (this.columnVirtualizer) {
          const indexes = this.columnVirtualizer.getVirtualIndexes();
          // * Adjust the index to account for left pinned columns
          // * Virtualizer: The index is only for center columns, so we need to add the left pinned count to get the actual index.
          // * Sortable / savedOrder: The index is for all columns.
          // * [Node] Usually this is unnecessary, since the virtual indexes should be in continuous order, but it's better to be safe.
          // eslint-disable-next-line @typescript-eslint/no-non-null-assertion
          oldIndex = indexes[oldIndex - leftPinnedCount]! + leftPinnedCount;
          // eslint-disable-next-line @typescript-eslint/no-non-null-assertion
          newIndex = indexes[newIndex - leftPinnedCount]! + leftPinnedCount;
        }
        const [moved] = savedOrder.splice(oldIndex, 1);
        savedOrder.splice(newIndex, 0, moved!);
        this.table.setColumnOrder(savedOrder);
        this.currentDragging = null;
      },
    });
  }

  updateTableOptions = () => {
    const { table } = this;

    table.setOptions((prev) => ({
      ...prev,
      state: {
        ...prev.state,
        ...this.getTableState(),
      },
    }));

    this.ksStateChange.emit(table.getState());
    forceUpdate(this);
  };

  private initializeTable() {
    const options = this.getTableOptions();

    this.table = createTableInstance({
      dataSource: this.dataSource,
      columns: this.columns,
      rowKey: this.rowKey,
      getSubRows: this.expandable?.canExpandRow,
      options,
      state: this.getTableState(),
      rowSelection: this.rowSelection,
      expandable: this.expandable,
    });
  }

  private get tableFeatureArgs(): TableFeatureArgs {
    const selectionFixed = this.rowSelection?.fixed;
    const expansionFixed = this.expandable?.fixed;
    const selectionColumn = this.rowSelection?.canSelectRow
      ? { key: SELECTION_COLUMN_ID, ...(selectionFixed ? { fixed: selectionFixed } : {}) }
      : undefined;
    const expansionColumn = this.expandable?.canExpandRow
      ? { key: TOGGLER_COLUMN_ID, ...(expansionFixed ? { fixed: expansionFixed } : {}) }
      : undefined;
    const bothRight = selectionColumn && expansionColumn && selectionFixed === 'right' && expansionFixed === 'right';
    const fixedColumns = (bothRight ? [expansionColumn, selectionColumn] : [selectionColumn, expansionColumn]).filter(
      Boolean,
    );
    const columns = [...fixedColumns, ...this.columns] as (TableColumn<RowData> | TableColumnGroup)[];

    return {
      manual: this.manual,
      columns,
      getTableInstance: () => this.table,
      updateTableOptions: this.updateTableOptions,
    };
  }

  private setInitialTableState() {
    [
      this.setInitialSortingState,
      this.setInitialExpandedState,
      this.setInitialPaginationState,
      this.setInitialRowPinningState,
      this.setInitialVisibilityState,
      this.setInitialColumnOrderState,
      this.setInitialColumnSizingState,
      this.setInitialRowSelectionState,
      this.setInitialColumnPinningState,
      this.setInitialColumnSizingInfoState,
    ].forEach((fn) => fn(this.tableFeatureArgs));
  }

  private getTableOptions() {
    return [
      this.getPinningFeatureOptions,
      this.getReorderFeatureOptions,
      this.getSortingFeatureOptions,
      this.getResizingFeatureOptions,
      this.getSelectionFeatureOptions,
      this.getPaginationFeatureOptions,
      this.getExpandableFeatureOptions,
      this.getVisibilityFeatureOptions,
    ].reduce<CreateTableInstanceProps['options']>((pre, cur) => merge(pre, cur(this.tableFeatureArgs)), {});
  }

  private getTableState(): Partial<TableState> {
    return {
      sorting: this.getSortingState(this.manual),
      expanded: this.getExpandedState(this.manual),
      rowPinning: this.getRowPinningState(this.manual),
      pagination: this.getPaginationState(this.manual),
      columnOrder: this.getColumnOrderState(),
      columnSizing: this.getColumnSizingState(this.manual),
      rowSelection: this.getRowSelectionState(this.manual),
      columnPinning: this.getColumnPinningState(),
      columnSizingInfo: this.getColumnSizingInfoState(),
      columnVisibility: this.getVisibilityState(),
    };
  }

  protected onResponsiveColumnWidthsChanged(): void {
    return;
  }

  protected ensurePercentageWidthObserver(): void {
    const widthElement = this.getWidthReferenceElement();

    if (!this.percentageWidthObserver) {
      this.percentageWidthObserver = new PercentageWidthObserver(widthElement, () => {
        this.conductColumnsAutoWidth();
      });
      return;
    }

    if (this.percentageWidthObserver.getElement() === widthElement) {
      return;
    }

    this.percentageWidthObserver.stop();
    this.percentageWidthObserver = new PercentageWidthObserver(widthElement, () => {
      this.conductColumnsAutoWidth();
    });
  }

  protected getWidthReferenceElement(): HTMLElement {
    return this.el;
  }

  protected abstract initializePinnedRows(): void;
  protected abstract scrollToTablePosition(options?: TableScrollToPositionOptions): void;
}
