import { xor } from 'lodash-es';
import { Prop, State, Event, type EventEmitter, type MixinFactory } from '@stencil/core';
import {
  getExpandedRowModel,
  type Row,
  type ExpandedOptions,
  type RowData,
  type ExpandedState,
} from '@byted-keystone/table';
import { DetailArgs } from '@src/shared/dom';
import { resolveUpdater } from '../helpers';
import type { TableExpandableConfig, TableFeatureArgs } from '../types';

export const ExpandableFactory = (Base: ReturnType<MixinFactory>) => {
  class TableExpandable extends Base {
    @State() internalExpandedState: ExpandedState = {};

    /** Expandable row configuration. Enables and customizes row expansion. */
    @Prop() expandable?: TableExpandableConfig;

    /** Emitted when the expanded row state changes. Emits the expanded state, expanded rows, and the row that changed. */
    @Event({ bubbles: false, composed: false }) ksExpandedStateChange!: EventEmitter<
      DetailArgs<[ExpandedState, Row<RowData>[], Row<RowData> | null]>
    >;

    constructor() {
      super();
    }

    assembleExpandedState = (expandedRowKeys: string[] = []): Record<string, boolean> =>
      Object.fromEntries(expandedRowKeys.map((key) => [key, true]));

    getExpandedState = (manual: boolean): ExpandedState =>
      manual ? this.assembleExpandedState(this.expandable?.expandedRowKeys) : this.internalExpandedState;

    setInitialExpandedState = () => {
      const initialExpandedState: ExpandedState = this.expandable?.canExpandRow
        ? this.assembleExpandedState(this.expandable.expandedRowKeys)
        : {};

      this.internalExpandedState = initialExpandedState;
    };

    getExpandableFeatureOptions = ({
      manual,
      getTableInstance,
      updateTableOptions,
    }: TableFeatureArgs): ExpandedOptions<RowData> =>
      this.expandable?.canExpandRow
        ? {
            enableExpanding: true,
            paginateExpandedRows: false,
            getExpandedRowModel: getExpandedRowModel(),
            onExpandedChange: (updater) => {
              const newExpandedState = resolveUpdater(updater, this.getExpandedState(manual));
              const expandedStateDiff = xor(Object.keys(newExpandedState), Object.keys(this.getExpandedState(manual)));
              if (!manual) {
                this.internalExpandedState = newExpandedState;
                updateTableOptions();
              }

              const table = getTableInstance();
              const expandedRows = Object.keys(newExpandedState).map((key) => table.getRow(key));
              const expandedChangedRow = expandedStateDiff.length ? table.getRow(expandedStateDiff[0]!) : null;
              this.ksExpandedStateChange.emit(DetailArgs(newExpandedState, expandedRows, expandedChangedRow));
            },
          }
        : {};
  }
  return TableExpandable;
};
