import { debounce } from 'lodash-es';
import { Prop, State, Event, Watch, type EventEmitter, type MixinFactory } from '@stencil/core';
import { dir } from '@src/shared/i18n';
import { resolveUpdater } from '../helpers';
import type { ColumnSizingInfoState, ColumnSizingOptions, ColumnSizingState } from '@byted-keystone/table';
import type { TableFeatureArgs, TableResizableConfig } from '../types';
import { asObject } from '@src/shared/type-utils';

const DEFAULT_SIZING_INFO_STATE: ColumnSizingInfoState = {
  columnSizingStart: [],
  deltaOffset: null,
  deltaPercentage: null,
  isResizingColumn: false,
  startOffset: null,
  startSize: null,
};

export const ResizingFactory = (Base: ReturnType<MixinFactory>) => {
  class TableResizing extends Base {
    @State() internalColumnSizingState: ColumnSizingState = {};
    @State() internalColumnSizingInfoState: ColumnSizingInfoState = DEFAULT_SIZING_INFO_STATE;

    /** Whether to enable resizable columns. */
    @Prop() resizable: boolean | TableResizableConfig = false;

    /** Custom event triggered when a column is resized. */
    @Event({ bubbles: false, composed: false }) ksResize!: EventEmitter<Record<string, number>>;

    constructor() {
      super();
    }

    reportResizeEvent: (event: Record<string, number>) => void = debounce((event: Record<string, number>) => {
      this.ksResize.emit(event);
    }, 200);

    getControlledColumnSizingState = (): ColumnSizingState => asObject(this.resizable)?.columnSizingState || {};

    @Watch('resizable')
    resizableChanged() {
      if (this.internalColumnSizingInfoState.isResizingColumn) return;

      const next = this.getControlledColumnSizingState();
      if (Object.keys(next).length) {
        this.internalColumnSizingState = next;
        this['updateTableOptions']();
      }
    }

    getColumnSizingState = (manual: boolean) => {
      if (!manual) return this.internalColumnSizingState;

      const hasInternal = Object.keys(this.internalColumnSizingState).length > 0;
      return hasInternal ? this.internalColumnSizingState : this.getControlledColumnSizingState();
    };

    getColumnSizingInfoState = () => this.internalColumnSizingInfoState;

    setInitialColumnSizingState = ({ manual }: TableFeatureArgs) => {
      this.internalColumnSizingState = manual ? this.getControlledColumnSizingState() : {};
    };

    setInitialColumnSizingInfoState = () => (this.internalColumnSizingInfoState = DEFAULT_SIZING_INFO_STATE);

    getResizingFeatureOptions = ({
      manual,
      updateTableOptions,
      getTableInstance,
    }: TableFeatureArgs): ColumnSizingOptions =>
      this.resizable
        ? {
            columnResizeMode: 'onChange',
            enableColumnResizing: true,
            columnResizeDirection: dir(),
            onColumnSizingChange: (updater) => {
              const raw = resolveUpdater(updater, this.internalColumnSizingState);
              const table = getTableInstance();

              const next = Object.keys(raw).reduce<ColumnSizingState>((acc, columnId) => {
                const value = raw[columnId] as number;
                const column = table.getColumn(columnId);

                if (!column) {
                  acc[columnId] = value;
                  return acc;
                }

                const { minSize, maxSize } = column.columnDef;

                let size = value;
                if (typeof minSize === 'number') size = Math.max(size, minSize);
                if (typeof maxSize === 'number') size = Math.min(size, maxSize);

                acc[columnId] = size;
                return acc;
              }, {});

              this.internalColumnSizingState = next;
              updateTableOptions();

              if (manual) {
                this.ksResize.emit(next);
              } else {
                this.reportResizeEvent(next);
              }
            },
            onColumnSizingInfoChange: (updater) => {
              const prev = this.internalColumnSizingInfoState;
              const next = resolveUpdater(updater, prev);

              this.internalColumnSizingInfoState = next;
              updateTableOptions();
            },
          }
        : {};
  }
  return TableResizing;
};
