/* eslint-disable max-lines */
import { Component, Element, State, Host, h, Prop, Watch, type ComponentInterface, VNode } from '@stencil/core';
import { throttle, noop } from 'lodash-es';
import { commonMessages } from '@fe-infra/keystone-locales';
import { t } from '@src/shared/i18n';
import { DetailArgs, traverseDOMTree } from '@src/shared/dom';
import { TableBodyRow, TableHeadRow, TableFootRow } from './components';
import { TableCore } from './core';
import { DEFAULT_PAGE_SIZE, TableFrameContactObserver } from './helpers';

import type { RowData, Row, Cell, HeaderGroup, HeaderContext, Header } from '@byted-keystone/table';
import type { CSSProperties } from '@src/shared/dom';
import type {
  TableSize,
  TableFrameMode,
  TableRowSelectionConfig,
  TableCellSkeletonConfig,
  TableExpandableConfig,
  TableScrollPosition,
  TableScrollToPositionOptions,
} from './types';

const prefix = 'table';

/**
 * @slot append - Content to display at the end of the table.
 * @slot empty - Content to display when the table has no data.
 * @part base - The base container of the component.
 */
@Component({
  tag: 'ks-table',
  styleUrl: 'ks-table.scss',
  shadow: true,
})
export class KsTable extends TableCore implements ComponentInterface {
  protected wrapperEl?: HTMLDivElement;
  private frameContactObserver = new TableFrameContactObserver(
    () => this.wrapperEl,
    () => this.getLastBodyCellElement(),
    () => this.getFrameBoundaryElement(),
  );
  protected wrapWithSlot: (slotName: string, children: unknown) => unknown = noop;
  protected wrapWithSlotWithFallback = (slotName: string, children: unknown) => {
    const wrappedChildren = this.wrapWithSlot(slotName, children);
    return wrappedChildren || this.wrapWithSlot(slotName, '');
  };
  protected setDynamicRenderDeps: (items: unknown[]) => void = noop;

  @Element() override el!: HTMLKsTableElement;

  @State() showTopPinningShadow = false;
  @State() showStartPinningShadow = false;
  @State() showEndPinningShadow = false;

  /** Visual density of the table, e.g. 'sm' | 'md'. */
  @Prop() size: TableSize = 'md';
  /** Whether the table is in loading state. */
  @Prop() loading = false;
  /** Whether to display borders around table cells. */
  @Prop() bordered = false;
  /** Whether the table frame fills the available height or follows content height. */
  @Prop() frameMode: TableFrameMode = 'fill';
  /** Estimated number of table rows, applied to the number of row skeletons during loading. */
  @Prop() estimatedCount?: number;
  /** The row alignment for table cells. */
  @Prop() rowAlign: 'start' | 'center' = 'center';
  /** Additional part name applied to each body row. */
  @Prop() rowPartName?: string | ((value: unknown, row: Row<RowData>, index: number) => string);

  /** Additional part name applied to each cell */
  @Prop() cellPartName?: string | ((value: unknown, cell: Cell<RowData, unknown>) => string);

  /** Additional part name applied to each cell content */
  @Prop() contentPartName?: string | ((value: unknown, cell: Cell<RowData, unknown>) => string);

  /** Custom skeleton config for each body cell. */
  @Prop() override cellSkeletonContent?: (cell: Cell<RowData, unknown>) => TableCellSkeletonConfig | undefined;

  /** Additional part name applied to each footer cell */
  @Prop() footerCellPartName?: string | ((headerContext: HeaderContext<RowData, unknown>) => string);

  /** Additional part name applied to each footer cell content */
  @Prop() footerContentPartName?: string | ((headerContext: HeaderContext<RowData, unknown>) => string);

  /** Additional part name applied to each header cell */
  @Prop() headerCellPartName?: string | ((headerContext: HeaderContext<RowData, unknown>) => string);

  /** Additional part name applied to each header cell content */
  @Prop() headerContentPartName?: string | ((headerContext: HeaderContext<RowData, unknown>) => string);

  /** Additional part name applied to each header cell inner content */
  @Prop() headerInnerContentPartName?: string | ((headerContext: HeaderContext<RowData, unknown>) => string);

  /** Key generator for slot key, default to use cell or header id. */
  @Prop() slotKey: (instance: Header<RowData, unknown> | Cell<RowData, unknown>) => string = (instance) => instance.id;

  // eslint-disable-next-line @stencil-community/no-unused-watch
  @Watch('rowSelection')
  protected override rowSelectionChanged(rowSelection: TableRowSelectionConfig) {
    super.rowSelectionChanged(rowSelection);
  }

  // eslint-disable-next-line @stencil-community/no-unused-watch
  @Watch('expandable')
  protected override expandableChanged(expandable: TableExpandableConfig) {
    super.expandableChanged(expandable);
  }

  override connectedCallback(): void {
    super.connectedCallback();

    if (!this.hasLoaded) {
      return;
    }

    this.initializeSortable();
    this.updateDynamicSlots();
    this.frameContactObserver.start();
  }

  override componentDidLoad(): void {
    super.componentDidLoad();
    this.initializeSortable();
    this.updateDynamicSlots();
    this.frameContactObserver.start();
  }

  componentDidUpdate(): void {
    this.updateDynamicSlots();
    this.frameContactObserver.sync();
    this.el.style.setProperty('--ks-comp-table-height', `${this.wrapperEl?.clientHeight || 0}px`);
  }

  override disconnectedCallback(): void {
    this.frameContactObserver.stop();
    super.disconnectedCallback();
  }

  protected getLastBodyCellElement(): HTMLElement | undefined {
    if (!this.bordered || (this.frameMode ?? 'fill') !== 'fill') return undefined;

    const lastRow = this.wrapperEl?.querySelector<HTMLElement>(`.${prefix}__tbody-row--last`);
    const cells = lastRow?.querySelectorAll<HTMLElement>(`.${prefix}__tbody-cell`);
    return cells?.[cells.length - 1];
  }

  protected getFrameBoundaryElement(): HTMLElement | undefined {
    if (!this.bordered || (this.frameMode ?? 'fill') !== 'fill') return undefined;

    return this.wrapperEl?.querySelector<HTMLElement>(`.${prefix}__tfoot`) ?? this.wrapperEl;
  }

  /**
   * @returns All the rows should be rendered currently */
  protected getTableRowModel() {
    return [...this.table.getTopRows(), ...this.table.getCenterRows(), ...this.table.getBottomRows()];
  }

  /* istanbul ignore next */
  protected updateDynamicSlots = () => {
    const rows = this.getTableRowModel();
    const headerGroups = this.table.getHeaderGroups();
    this.setDynamicRenderDeps([
      ...this.getDynamicSlots({ rows, headerGroups }),
      ...Object.values(this.headerDynamicRenderDeps).flat(),
    ]);
  };

  /* istanbul ignore next */
  protected getDynamicSlots({ rows, headerGroups }: { rows: Row<RowData>[]; headerGroups: HeaderGroup<RowData>[] }) {
    const renderedNodes: unknown[] = [];

    headerGroups.forEach((headerGroup) => {
      headerGroup.headers.forEach((header) => {
        if (header.isPlaceholder) return;
        const { header: headerRenderer, footer: footerRenderer } = header.column.columnDef;

        if (typeof headerRenderer === 'function') {
          const renderer = headerRenderer(header.getContext());
          if (typeof renderer === 'function') {
            renderedNodes.push(
              this.wrapWithSlotWithFallback(`title-${this.slotKey(header)}`, renderer(header.getContext())),
            );
          }

          if (header.id === this.currentDragging && typeof renderer === 'function') {
            // render a mask for dragging render
            renderedNodes.push(
              this.wrapWithSlotWithFallback(`title-${header.id}--mask`, renderer(header.getContext())),
            );
          }
        }

        if (typeof footerRenderer === 'function') {
          const renderer = footerRenderer(header.getContext());
          if (typeof renderer === 'function') {
            renderedNodes.push(
              this.wrapWithSlotWithFallback(`footer-${this.slotKey(header)}`, renderer(header.getContext())),
            );
          }
        }
      });
    });

    rows.forEach((row) => {
      row.getVisibleCells().forEach((cell) => {
        const renderer = cell.column.columnDef.cell;
        if (typeof renderer === 'function' && renderer.length < 1) {
          const cellContent = renderer({} as never)(cell.getValue(), row, row.index);
          renderedNodes.push(this.wrapWithSlotWithFallback(`cell-${this.slotKey(cell)}`, cellContent));
        }
      });
    });

    return renderedNodes;
  }

  // eslint-disable-next-line @stencil-community/own-methods-must-be-private
  override initializeSortable() {
    const el = this.el.shadowRoot?.querySelector<HTMLTableRowElement>(`.${prefix}__thead tr`);
    if (el) {
      super.initializeSortable(el, {
        draggable: `.${prefix}__thead-cell`,
        filter: `.${prefix}__thead-cell--pinned`,
        handle: `.${prefix}__dragger`,
        forceFallback: true,
        dragClass: `${prefix}__column-drag-mask`,
        ghostClass: `${prefix}__thead-cell--ghost`,
        easing: 'var(--ks-transition-easing-standardInOut)',
        dataIdAttr: 'data-column-id',
        animation: 200,
        onStart: () => {
          const headerHeight = el.offsetHeight;
          const totalHeight = this.wrapperEl?.offsetHeight || 0;
          const guideHeight = totalHeight - headerHeight;

          const dragMask = this.el.shadowRoot?.querySelector<HTMLElement>(`.${prefix}__column-drag-mask`);
          if (dragMask && guideHeight > 0) {
            traverseDOMTree(dragMask, (el) => {
              if (el instanceof HTMLSlotElement) {
                el.name += '--mask';
              }
            });
            dragMask.style.setProperty('--ks-comp-drag-guide-height', `${guideHeight}px`);
            dragMask.style.setProperty('opacity', '1');
          }
        },
      });
    }
  }

  protected getScrollPosition(el: HTMLDivElement): TableScrollPosition {
    const { direction = 'ltr' } = getComputedStyle(el);
    const scrollLeft = el.scrollLeft * (direction === 'rtl' ? -1 : 1);
    const isAtTop = el.scrollTop <= 0;
    const isAtBottom = el.scrollTop + el.clientHeight >= el.scrollHeight;
    const isAtStart = scrollLeft <= 0;
    const isAtEnd = scrollLeft + el.clientWidth >= el.scrollWidth;

    return {
      scrollTop: el.scrollTop,
      scrollLeft,
      clientHeight: el.clientHeight,
      clientWidth: el.clientWidth,
      scrollHeight: el.scrollHeight,
      scrollWidth: el.scrollWidth,
      isAtTop,
      isAtBottom,
      isAtStart,
      isAtEnd,
    };
  }

  protected updateScrollState(position: TableScrollPosition) {
    this.showTopPinningShadow = !position.isAtTop;
    this.showStartPinningShadow = !position.isAtStart;
    this.showEndPinningShadow = !position.isAtEnd;
  }

  protected scrollToWrapper({ top, left, behavior }: TableScrollToPositionOptions = {}) {
    const { wrapperEl } = this;
    if (!wrapperEl) return;

    wrapperEl.scrollTo({
      top: top ?? wrapperEl.scrollTop,
      left: left ?? wrapperEl.scrollLeft,
      behavior,
    });
  }

  protected override initializePinnedRows() {
    const thead = this.el.shadowRoot?.querySelector<HTMLElement>(`.${prefix}__thead`);
    let currentOffset = thead ? thead.offsetHeight : 0;
    const pinnedRows = this.el.shadowRoot?.querySelectorAll<HTMLTableRowElement>(`.${prefix}__tbody-row--pinned`);

    if (!pinnedRows) return;

    pinnedRows.forEach((row) => {
      row.style.top = `${currentOffset}px`;
      currentOffset += row.offsetHeight;
    });
  }

  protected onWrapperScroll: EventListener = throttle((e: Event) => {
    const el = e.target as HTMLDivElement;
    const position = this.getScrollPosition(el);

    this.updateScrollState(position);
    this.ksScrollPositionChange.emit(position);
  });

  protected override scrollToTablePosition(options?: TableScrollToPositionOptions): void {
    this.scrollToWrapper(options);
  }

  protected handleRowClick = (row: Row<RowData>) => {
    this.ksRowClick.emit(row.original);
  };

  protected handleRowHover = (row: Row<RowData>) => {
    this.ksRowHover.emit(row.original);
  };

  protected handleRowHoverEnd = (row: Row<RowData>) => {
    this.ksRowHoverEnd.emit(row.original);
  };

  protected handleCellPointerEnter = (cell: Cell<RowData, unknown>) => {
    const { row, column } = cell.getContext();
    this.ksCellPointerEnter.emit({ row, column, cell });
  };

  protected handleCellPointerLeave = (cell: Cell<RowData, unknown>) => {
    const { row, column } = cell.getContext();
    this.ksCellPointerLeave.emit({ row, column, cell });
  };

  protected getSortedVisibleFlatColumns = () => {
    const columnOrder = this.getColumnOrderState();
    const getColumnOrderIndex = (id: string) => {
      const index = columnOrder.indexOf(id);
      return index === -1 ? Number.MAX_SAFE_INTEGER : index;
    };

    return [...this.table.getVisibleFlatColumns()].sort(
      (a, b) => getColumnOrderIndex(a.id) - getColumnOrderIndex(b.id),
    );
  };

  protected override getWidthReferenceElement(): HTMLElement {
    return this.wrapperEl || this.el;
  }

  protected getColumnWidthCssVariables = (sortedColumns = this.getSortedVisibleFlatColumns()) =>
    sortedColumns.reduce(
      ({ cssProperties, totalSize: preSize }, cur) => {
        const size = cur.getSize();
        const totalSize = preSize + size;
        cssProperties[`--ks-comp-width-table-column-${cur.id}`] = `${size}`;
        return { cssProperties, totalSize };
      },
      {
        cssProperties: {} as Exclude<CSSProperties, undefined>,
        totalSize: 0,
      },
    );

  protected getCssVariables = (): CSSProperties => this.getColumnWidthCssVariables().cssProperties;

  private setPage = ({ detail }: CustomEvent<number>) => {
    // Tanstack table page index is 0-based, so we need to subtract 1
    this.table.setPageIndex(detail - 1);
  };
  private setPageSize = ({ detail }: CustomEvent<number>) => {
    this.table.setPageSize(detail);
  };
  protected renderPagination() {
    const { pagination, table } = this;
    const { pageIndex, pageSize } = table.getState().pagination;

    if (pagination === false) return null;

    return (
      <ks-pagination
        class={`${prefix}__pagination`}
        page={pageIndex + 1}
        pageSize={pageSize}
        pageSizeOptions={pagination?.pageSizeList}
        total={table.getRowCount()}
        showPageSizeChanger={!!pagination?.pageSizeList?.length}
        onKsPageChange={this.setPage}
        onKsPageSizeChange={this.setPageSize}
        data-testid="ks-simple-table-ks-simple-table-obQLBt"
      />
    );
  }

  protected renderSkeletonRows() {
    const { estimatedCount = DEFAULT_PAGE_SIZE, table } = this;

    const columnsCount = table.getVisibleFlatColumns().length;

    return Array.from({ length: estimatedCount }, () => (
      <tr class={`${prefix}__tbody-row`}>
        {Array.from({ length: columnsCount }, () => (
          <td class={`${prefix}__cell ${prefix}__tbody-cell`}>
            <div class={`${prefix}__cell-content`}>
              <div class={`${prefix}__skeleton animate-pulse`} />
            </div>
          </td>
        ))}
      </tr>
    ));
  }

  protected renderEmptyState(virtual = false) {
    const columns = this.table.getVisibleFlatColumns();
    const columnsCount = columns.length;

    let widthStyle: string | undefined;

    if (virtual && columnsCount) {
      const sumVar = columns.map((c) => `var(--ks-comp-width-table-column-${c.id})`).join(' + ');
      widthStyle = `calc((${sumVar}) * 1px)`;
    }

    return (
      <tr
        aria-hidden="true"
        style={{
          width: widthStyle,
          height: '100%',
        }}
      >
        <td
          colSpan={columnsCount}
          class={{
            [`${prefix}__cell--empty`]: true,
          }}
        >
          <slot name="empty">
            <ks-empty-state title={t(commonMessages.empty)} />
          </slot>
        </td>
      </tr>
    );
  }

  // eslint-disable-next-line max-lines-per-function
  render() {
    const {
      bordered,
      columns,
      dataSource,
      draggable,
      resizable,
      size,
      loading,
      expandable,
      rowSelection,
      showTopPinningShadow,
      showStartPinningShadow,
      showEndPinningShadow,
      table,
    } = this;

    const rows = this.getTableRowModel();

    const enableTableFooter = columns.some((column) =>
      'columns' in column ? column.columns.some((subColumn) => subColumn.footer) : column.footer,
    );

    const hasPinnedRows = rows.some((row) => row.getIsPinned() === 'top');
    const visibleRows = rows.filter((row) => !row.getParentRow() || row.getParentRow()?.getIsExpanded());
    const lastBodyRow = visibleRows[visibleRows.length - 1];
    const frameMode = this.frameMode ?? 'fill';
    const isFrameFill = frameMode === 'fill';
    const shouldRenderFrameFiller = isFrameFill && (dataSource.length > 0 || loading);

    return (
      <Host class="KsTable" style={this.getCssVariables()}>
        <div
          class={{
            [`${prefix}__content`]: true,
            [`${prefix}__content--frame-${frameMode}`]: true,
          }}
        >
          <div
            ref={(el) => {
              if (el) this.wrapperEl = el;
            }}
            part="base"
            class={{
              [`${prefix}__wrapper`]: true,
              [`${prefix}__wrapper--bordered`]: Boolean(bordered),
              [`${prefix}__wrapper--frame-${frameMode}`]: true,
            }}
            onScroll={this.onWrapperScroll}
            data-testid="ks-simple-table-ks-simple-table-xhTQoc"
          >
            <table
              class={{
                [prefix]: true,
                [`${prefix}--${size}`]: true,
                [`${prefix}--bordered`]: Boolean(bordered),
                [`${prefix}--top-shadowed`]: showTopPinningShadow,
                [`${prefix}--start-shadowed`]: showStartPinningShadow,
                [`${prefix}--end-shadowed`]: showEndPinningShadow,
              }}
            >
              <colgroup>
                {this.getSortedVisibleFlatColumns().map(({ id, columnDef }) => (
                  <col
                    key={`col-${id}`}
                    style={{
                      width: `calc(var(--ks-comp-width-table-column-${id}) * 1px)`,
                      minWidth: columnDef.minSize ? `${columnDef.minSize}px` : undefined,
                      maxWidth: columnDef.maxSize ? `${columnDef.maxSize}px` : undefined,
                    }}
                    data-testid={`ks-simple-table-ks-simple-table-7YYRXF-${`col-${id}`}`}
                  />
                ))}
              </colgroup>

              <thead class={`${prefix}__thead`}>
                {table.getHeaderGroups().map((headerGroup) => (
                  <TableHeadRow
                    key={headerGroup.id}
                    prefix={prefix}
                    table={table}
                    rowSelection={this.rowSelection}
                    draggable={draggable}
                    headers={headerGroup.headers}
                    resizable={resizable}
                    isLastPinned={!hasPinnedRows}
                    onAction={(action, header) => {
                      // Compatible with old logic
                      if (['clear-sort', 'sort-ascending', 'sort-descending'].includes(action)) {
                        this.ksSorterClick.emit({ id: header.column.id, direction: header.column.getIsSorted() });
                      }
                      this.ksAction.emit(DetailArgs(action, header.column));
                    }}
                    contentPartName={this.headerContentPartName}
                    innerContentPartName={this.headerInnerContentPartName}
                    cellPartName={this.headerCellPartName}
                    slotKey={this.slotKey}
                    wrapWithSlot={this.wrapWithSlot}
                    passThroughSlots={this.passThroughSlots}
                    // eslint-disable-next-line react/jsx-no-bind
                    setDynamicRenderDeps={(
                      headerId: string,
                      children: unknown[],
                      getPassThroughSlots?: () => VNode[],
                    ) => {
                      this.headerDynamicRenderDeps[headerId] = children;
                      this.passThroughSlots = {
                        ...this.passThroughSlots,
                        [headerId]: getPassThroughSlots?.() || [],
                      };
                    }}
                    data-testid="ks-simple-table-ks-simple-table-sAVogH"
                  />
                ))}
              </thead>

              <tbody class={`${prefix}__tbody`}>
                {!dataSource.length && (loading ? this.renderSkeletonRows() : this.renderEmptyState())}

                {rows.map((row, index) => {
                  const isPinned = row.getIsPinned() === 'top';
                  const nextRow = rows[index + 1];
                  const isLastPinned = isPinned && (!nextRow || nextRow.getIsPinned() !== 'top');

                  return (
                    <TableBodyRow<RowData>
                      key={row.id}
                      part={
                        typeof this.rowPartName === 'function'
                          ? this.rowPartName(row.original, row, row.index)
                          : this.rowPartName
                      }
                      prefix={prefix}
                      row={row}
                      rowAlign={this.rowAlign}
                      loading={loading}
                      hideToggler={!(expandable?.shouldShowToggler?.(row) ?? true)}
                      hideSelection={!(rowSelection?.shouldShowSelection?.(row) ?? true)}
                      isLastPinned={isLastPinned}
                      isLastBodyRow={row === lastBodyRow}
                      contentPartName={this.contentPartName}
                      cellPartName={this.cellPartName}
                      cellSkeletonContent={this.cellSkeletonContent}
                      onRowClick={this.handleRowClick}
                      onRowHover={this.handleRowHover}
                      onRowHoverEnd={this.handleRowHoverEnd}
                      onCellPointerEnter={this.handleCellPointerEnter}
                      onCellPointerLeave={this.handleCellPointerLeave}
                      slotKey={this.slotKey}
                      data-testid={`ks-simple-table-ks-simple-table-vV6zYc-${row.id}`}
                    />
                  );
                })}
                <slot name="append" />
                {shouldRenderFrameFiller && (
                  <tr class={`${prefix}__tbody-row--frame-filler`} aria-hidden="true">
                    <td colSpan={this.getSortedVisibleFlatColumns().length} />
                  </tr>
                )}
              </tbody>

              {enableTableFooter && (
                <tfoot class={`${prefix}__tfoot`}>
                  {table.getFooterGroups().map((footerGroup) => (
                    <TableFootRow
                      prefix={prefix}
                      headers={footerGroup.headers}
                      loading={loading}
                      contentPartName={this.footerContentPartName}
                      cellPartName={this.footerCellPartName}
                      slotKey={this.slotKey}
                    />
                  ))}
                </tfoot>
              )}
            </table>
          </div>
          {frameMode === 'content' && <div class={`${prefix}__spacer`} aria-hidden="true" />}
        </div>

        {this.renderPagination()}
      </Host>
    );
  }

  @State() protected passThroughSlots: Record<string, VNode[]> = {};
  protected headerDynamicRenderDeps: Record<string, unknown[]> = {};

  ////// DEPS //////
  protected __DEPS__() {
    return [<ks-dropdown-button />];
  }
}
