import { h, type FunctionalComponent } from '@stencil/core';
import { SvgCheck, SvgCheckIndeterminate } from '@src/components/ks-checkbox/SvgCheck';

interface ITableSelectionCheckboxProps {
  checked: boolean;
  indeterminate?: boolean;
  disabled?: boolean;
  onChange?: (checked: boolean) => void;
  'aria-label'?: string;
  'data-testid'?: string;
}

export const TableSelectionCheckbox: FunctionalComponent<ITableSelectionCheckboxProps> = ({
  checked,
  indeterminate,
  disabled,
  onChange,
  'aria-label': ariaLabel,
  'data-testid': dataTestId,
}) => {
  let inputElement: HTMLInputElement | undefined;

  function stopPropagation(event: Event) {
    event.stopPropagation();
  }

  function syncIndeterminate(element?: HTMLInputElement) {
    if (!element) return;
    element.indeterminate = Boolean(indeterminate);
  }

  function handleInputRef(element?: HTMLInputElement) {
    inputElement = element;
    syncIndeterminate(inputElement);
  }

  function handleChange(event: Event) {
    stopPropagation(event);
    syncIndeterminate(inputElement);
    onChange?.((event.target as HTMLInputElement).checked);
  }

  return (
    <span
      class={{
        'table__selection-checkbox': true,
        'table__selection-checkbox--checked': checked,
        'table__selection-checkbox--indeterminate': Boolean(indeterminate),
        'table__selection-checkbox--disabled': Boolean(disabled),
      }}
      // eslint-disable-next-line react/jsx-no-bind
      onClick={stopPropagation}
      // eslint-disable-next-line react/jsx-no-bind
      onPointerDown={stopPropagation}
      data-testid={dataTestId}
    >
      <span class="table__selection-checkbox__display">
        <input
          ref={handleInputRef}
          class="table__selection-checkbox__input"
          type="checkbox"
          checked={checked}
          disabled={disabled}
          aria-label={ariaLabel}
          aria-checked={indeterminate ? 'mixed' : checked ? 'true' : 'false'}
          // eslint-disable-next-line react/jsx-no-bind
          onClick={stopPropagation}
          // eslint-disable-next-line react/jsx-no-bind
          onPointerDown={stopPropagation}
          // eslint-disable-next-line react/jsx-no-bind
          onChange={handleChange}
        />
        {checked && !indeterminate && <SvgCheck className="table__selection-checkbox__icon" />}
        {indeterminate && <SvgCheckIndeterminate className="table__selection-checkbox__icon" />}
      </span>
    </span>
  );
};
