import { Event, Prop, State, type EventEmitter, type MixinFactory } from '@stencil/core';
import { getSortedRowModel, type SortingOptions, type RowData, type SortingState } from '@byted-keystone/table';
import { resolveUpdater } from '../helpers';
import type { TableSortingConfig, TableFeatureArgs } from '../types';

export const SortingFactory = (Base: ReturnType<MixinFactory>) => {
  class TableSorting extends Base {
    @State() internalSortingState: SortingState = [];

    /** Sorting configuration. */
    @Prop() sorting: TableSortingConfig = [];

    /** Emitted when the sorting state changes. Emits the next sorting configuration. */
    @Event({ bubbles: false, composed: false }) ksSortingStateChange!: EventEmitter<SortingState>;

    constructor() {
      super();
    }

    getSortingState = (manual: boolean): SortingState => (manual ? this.sorting : this.internalSortingState);

    setInitialSortingState = () => {
      this.internalSortingState = this.sorting || [];
    };

    getSortingFeatureOptions = ({
      manual,
      columns,
      updateTableOptions,
    }: TableFeatureArgs): SortingOptions<RowData> => ({
      enableSorting: columns.some((column) =>
        'columns' in column ? column.columns.some((subColumn) => subColumn.sorter) : column.sorter,
      ),
      manualSorting: manual,
      getSortedRowModel: getSortedRowModel(),
      onSortingChange: (updater) => {
        const newSortingState = resolveUpdater(updater, this.getSortingState(manual));
        if (!manual) {
          this.internalSortingState = newSortingState;
          updateTableOptions();
        }
        this.ksSortingStateChange.emit(newSortingState);
      },
    });
  }
  return TableSorting;
};
