import { h, type FunctionalComponent } from '@stencil/core';
import { SELECTION_COLUMN_ID, renderFooterCell } from '../helpers';
import { JSXBase } from '@stencil/core/internal';
import type { RowData, Column, Header, HeaderContext } from '@byted-keystone/table';

interface ITableFootRowProps<TData> extends JSXBase.HTMLAttributes<HTMLTableRowElement> {
  prefix: string;
  headers: Header<TData, unknown>[];
  virtual?: boolean;
  loading?: boolean;
  visibleColumns?: Column<TData, unknown>[];
  contentPartName?: string | ((headerContext: HeaderContext<TData, unknown>) => string);
  cellPartName?: string | ((headerContext: HeaderContext<TData, unknown>) => string);
  slotKey: (instance: Header<TData, unknown>) => string;
}

export const TableFootRow = <TData extends RowData>(props: ITableFootRowProps<TData>): FunctionalComponent => {
  const { headers, prefix, virtual, loading, visibleColumns, contentPartName, cellPartName, slotKey, ...restProps } =
    props;

  const lastLeftPinnedIndex = headers.find((h) => h.column.getIsLastColumn('left'))?.index ?? -1;
  const firstRightPinnedIndex = headers.find((h) => h.column.getIsFirstColumn('right'))?.index ?? -1;
  const firstCenterHeaderIndex = virtual ? headers.findIndex((header) => !header.column.getIsPinned()) : -1;
  const lastCenterHeaderIndex = virtual
    ? headers.reduce((lastIndex, header, index) => (!header.column.getIsPinned() ? index : lastIndex), -1)
    : -1;

  return (
    <tr class={`${prefix}__tfoot-row`} {...restProps}>
      {headers.map((header, index) => {
        const columnSpan =
          typeof header.column.columnDef.meta?.colSpan === 'function'
            ? header.column.columnDef.meta.colSpan(null, 'footer')
            : header.column.columnDef.meta?.colSpan;

        // Set colSpan to 0 on the element will won't work, so we need to return null here.
        if (columnSpan === 0) return null;

        const effectiveSpan = columnSpan ?? 1;
        const columnAlign = header.column.columnDef.meta?.align;
        const columnPinningPosition = header.column.getIsPinned();
        const isLastLeftPinnedColumn =
          columnPinningPosition === 'left' &&
          lastLeftPinnedIndex !== -1 &&
          header.index <= lastLeftPinnedIndex &&
          lastLeftPinnedIndex < header.index + effectiveSpan;
        const isFirstRightPinnedColumn =
          columnPinningPosition === 'right' &&
          firstRightPinnedIndex !== -1 &&
          header.index <= firstRightPinnedIndex &&
          firstRightPinnedIndex < header.index + effectiveSpan;

        let widthStyle = virtual ? `calc(var(--ks-comp-width-table-column-${header.column.id}) * 1px)` : undefined;

        if (virtual && columnSpan !== undefined && columnSpan > 1 && visibleColumns) {
          const currentIndex = visibleColumns.findIndex((c) => c.id === header.column.id);
          if (currentIndex !== -1) {
            const spannedColumns = visibleColumns.slice(currentIndex, currentIndex + columnSpan);
            if (spannedColumns.length > 0) {
              const sumVar = spannedColumns.map((c) => `var(--ks-comp-width-table-column-${c.id})`).join(' + ');
              widthStyle = `calc((${sumVar}) * 1px)`;
            }
          }
        }

        return (
          <th
            key={header.id}
            colSpan={columnSpan}
            class={{
              [`${prefix}__cell`]: true,
              [`${prefix}__cell--align-${columnAlign}`]: Boolean(columnAlign),
              [`${prefix}__cell--pinned`]: Boolean(columnPinningPosition),
              [`${prefix}__cell--start-shadow`]: isFirstRightPinnedColumn,
              [`${prefix}__cell--end-shadow`]: isLastLeftPinnedColumn,
              [`${prefix}__tfoot-cell`]: true,
            }}
            style={{
              width: widthStyle,
              marginInlineStart:
                index === firstCenterHeaderIndex ? 'var(--ks-comp-table-virtual-padding-start)' : undefined,
              marginInlineEnd: index === lastCenterHeaderIndex ? 'var(--ks-comp-table-virtual-padding-end)' : undefined,
              insetInlineStart: columnPinningPosition === 'left' ? `${header.column.getStart('left')}px` : undefined,
              insetInlineEnd: columnPinningPosition === 'right' ? `${header.column.getAfter('right')}px` : undefined,
            }}
            part={typeof cellPartName === 'function' ? cellPartName(header.getContext()) : cellPartName}
            data-testid={`components-table-foot-row-pzJ1sk-${header.id}`}
          >
            <div
              class={`${prefix}__cell-content`}
              part={typeof contentPartName === 'function' ? contentPartName(header.getContext()) : contentPartName}
            >
              {header.column.id === SELECTION_COLUMN_ID &&
                (loading ? <div class={`${prefix}__skeleton--selection animate-pulse`} /> : null)}
              {header.column.id !== SELECTION_COLUMN_ID &&
                (loading ? (
                  <div class={`${prefix}__skeleton animate-pulse`} />
                ) : (
                  renderFooterCell(header.column.columnDef.footer, header.getContext(), slotKey)
                ))}
            </div>
          </th>
        );
      })}
    </tr>
  );
};
