export class TableFrameContactObserver {
  private ro?: ResizeObserver;
  private wrapper?: HTMLElement;
  private isTouching?: boolean;

  constructor(
    private getWrapper: () => HTMLElement | undefined,
    private getLastBodyCell: () => HTMLElement | undefined,
    private getBoundary: () => HTMLElement | undefined,
    private onChange?: (isTouching: boolean) => void,
  ) {}

  private onScroll = () => this.sync();

  start() {
    const wrapper = this.getWrapper();
    if (!wrapper) return;

    if (wrapper !== this.wrapper) {
      this.stop();
      this.wrapper = wrapper;
      this.wrapper.addEventListener('scroll', this.onScroll);
    }

    if (!this.ro) {
      this.ro = new ResizeObserver(() => this.sync());
      this.ro.observe(wrapper);
    }
    this.sync();
  }

  sync() {
    const wrapper = this.getWrapper();
    const lastBodyCell = this.getLastBodyCell();
    const boundary = this.getBoundary();
    const distance =
      lastBodyCell && boundary
        ? (boundary === wrapper ? boundary.getBoundingClientRect().bottom : boundary.getBoundingClientRect().top) -
          lastBodyCell.getBoundingClientRect().bottom
        : Infinity;
    const next = Math.abs(distance) <= 1;

    if (next === this.isTouching) return;
    this.isTouching = next;
    if (next) {
      wrapper?.classList.add('table__wrapper--frame-contact');
    } else {
      wrapper?.classList.remove('table__wrapper--frame-contact');
    }
    this.onChange?.(next);
  }

  stop() {
    this.ro?.disconnect();
    this.ro = undefined;
    this.wrapper?.removeEventListener('scroll', this.onScroll);
    this.wrapper?.classList.remove('table__wrapper--frame-contact');
    this.wrapper = undefined;
    this.isTouching = undefined;
  }
}
