import { Prop, State, type MixinFactory } from '@stencil/core';
import Sortable from 'sortablejs';
import type { ColumnOrderOptions, ColumnOrderState } from '@byted-keystone/table';
import { Virtualizer } from '@tanstack/virtual-core';
import { resolveUpdater } from '../helpers';
import type { TableColumn, TableFeatureArgs } from '../types';

export const ReorderFactory = (Base: ReturnType<MixinFactory>) => {
  class TableReorder extends Base {
    @State() sortable?: Sortable;
    @State() internalColumnOrderState: ColumnOrderState = [];
    @State() currentDragging: string | null = null;

    public columnVirtualizer?: Virtualizer<HTMLDivElement, HTMLTableCellElement>;

    /** Whether to enable draggable columns. */
    @Prop() draggable = false;

    constructor() {
      super();
    }

    initializeSortable(el: HTMLElement, options: Sortable.Options) {
      if (!this.draggable) return;

      this.sortable = Sortable.create(el, options);
    }

    getColumnOrderState = () => this.internalColumnOrderState;

    setInitialColumnOrderState = ({ columns }: TableFeatureArgs) => {
      const initialColumnOrderState = this.draggable
        ? columns
            .filter((column) =>
              'columns' in column ? column.columns.some((subColumn) => !subColumn.hidden) : !column.hidden,
            )
            .sort((a: TableColumn, b: TableColumn) => {
              const aIndex = a.fixed === 'left' ? -1 : a.fixed === 'right' ? 0 : 1;
              const bIndex = b.fixed === 'left' ? -1 : b.fixed === 'right' ? 0 : 1;
              return aIndex - bIndex;
            })
            .map((column) => column.key as string)
        : [];

      this.internalColumnOrderState = initialColumnOrderState;
    };

    getReorderFeatureOptions = ({ updateTableOptions }: TableFeatureArgs): ColumnOrderOptions => ({
      onColumnOrderChange: (updater) => {
        const newColumnOrderState = resolveUpdater(updater, this.getColumnOrderState());
        this.internalColumnOrderState = newColumnOrderState;
        updateTableOptions();
      },
    });
  }
  return TableReorder;
};
