/* eslint-disable @typescript-eslint/no-explicit-any */
import { h, VNode } from '@stencil/core';
import type { Cell, CellContext, Header, HeaderContext, RowData } from '@byted-keystone/table';

export const renderBodyCell = <TData extends RowData>(
  comp: any,
  props: CellContext<TData, unknown>,
  slotKey: (instance: Cell<TData, unknown>) => string,
  skeleton: VNode,
) => {
  const renderer = comp(props);
  return typeof renderer === 'function' ? <slot name={`cell-${slotKey(props.cell)}`}>{skeleton}</slot> : renderer;
};

export const renderHeaderCell = <TData extends RowData>(
  comp: any,
  props: HeaderContext<TData, unknown>,
  slotKey: (instance: Header<TData, unknown>) => string,
) => {
  /* istanbul ignore next */
  if (typeof comp === 'function') {
    const renderer = comp(props);
    return typeof renderer === 'function' ? <slot name={`title-${slotKey(props.header)}`} /> : renderer;
  }
  return comp;
};

export const renderFooterCell = <TData extends RowData>(
  comp: any,
  props: HeaderContext<TData, unknown>,
  slotKey: (instance: Header<TData, unknown>) => string,
) => {
  /* istanbul ignore next */
  if (typeof comp === 'function') {
    const renderer = comp(props);
    return typeof renderer === 'function' ? <slot name={`footer-${slotKey(props.header)}`} /> : renderer;
  }
  return comp;
};
