import { Event, Prop, State, type EventEmitter, type MixinFactory } from '@stencil/core';
import { map, mapValues, groupBy, filter, some } from 'lodash-es';
import { resolveUpdater } from '../helpers';
import type {
  RowData,
  RowPinningState,
  RowPinningOptions,
  ColumnPinningState,
  ColumnPinningOptions,
} from '@byted-keystone/table';
import type { TableRowPinningConfig, TableFeatureArgs } from '../types';

const DEFAULT_ROW_PINNING_STATE: RowPinningState = { top: [] };
const DEFAULT_COLUMN_PINNING_STATE: ColumnPinningState = { left: [], right: [] };

export const PinningFactory = (Base: ReturnType<MixinFactory>) => {
  class TablePinning extends Base {
    @State() internalRowPinningState: RowPinningState = DEFAULT_ROW_PINNING_STATE;
    @State() internalColumnPinningState: ColumnPinningState = DEFAULT_COLUMN_PINNING_STATE;

    /** Row pinning configuration to fix rows to the top or bottom. */
    @Prop() rowPinning?: TableRowPinningConfig;

    /** Emitted when the pinned row state changes. Emits the current row pinning state. */
    @Event({ bubbles: false, composed: false }) ksRowPinningStateChange!: EventEmitter<RowPinningState>;

    constructor() {
      super();
    }

    getRowPinningState = (manual: boolean): RowPinningState =>
      manual ? { top: this.rowPinning?.top } : this.internalRowPinningState;

    getColumnPinningState = (): ColumnPinningState => this.internalColumnPinningState;

    setInitialRowPinningState = () => {
      const initialRowPinningState = this.rowPinning?.top ? { top: this.rowPinning.top } : DEFAULT_ROW_PINNING_STATE;

      this.internalRowPinningState = initialRowPinningState;
    };

    setInitialColumnPinningState = ({ columns }: TableFeatureArgs) => {
      const initialColumnPinningState = mapValues(groupBy(filter(columns, 'fixed'), 'fixed'), (items) =>
        map(items, 'key'),
      );

      this.internalColumnPinningState = initialColumnPinningState;
    };

    getPinningFeatureOptions = ({
      manual,
      columns,
      updateTableOptions,
    }: TableFeatureArgs): RowPinningOptions<RowData> & ColumnPinningOptions => {
      const { top = [], keepPinnedRows } = this.rowPinning || {};

      const enableRowPinning = top.length > 0;
      const enableColumnPinning = some(columns, 'fixed');

      return {
        enableRowPinning,
        enableColumnPinning,
        keepPinnedRows,
        onRowPinningChange: (updater) => {
          const newRowPinningState = resolveUpdater(updater, this.getRowPinningState(manual));
          if (!manual) {
            this.internalRowPinningState = newRowPinningState;
            updateTableOptions();
          }
          this.ksRowPinningStateChange.emit(newRowPinningState);
        },
      };
    };
  }
  return TablePinning;
};
