import {
  createTable,
  createColumnHelper,
  getCoreRowModel,
  noop,
  type TableOptions,
  type CoreOptions,
  type RowData,
  type TableState,
  type ColumnDef,
  type ColumnHelper,
  type Updater,
  Header,
} from '@byted-keystone/table';
import { logger } from '@src/shared/unclassified/logger';
import { memo, SELECTION_COLUMN_ID, TOGGLER_COLUMN_ID } from '.';
import type { KsTable } from '../ks-table';
import type { TableColumn } from '../types';
import { DropdownItem } from '@src/components/ks-dropdown-menu-list/types';

const SELECTION_COLUMN_SIZE = 52;
const TOGGLER_COLUMN_SIZE = 24;

export const resolveUpdater = <T>(updater: Updater<T>, old: T): T =>
  typeof updater === 'function' ? (updater as (old: T) => T)(old) : updater;

export interface CreateTableInstanceProps extends Pick<
  KsTable,
  'dataSource' | 'columns' | 'rowKey' | 'rowSelection' | 'expandable'
> {
  getSubRows?: CoreOptions<RowData>['getSubRows'];
  options: Omit<TableOptions<RowData>, keyof CoreOptions<RowData>>;
  state: Partial<TableState>;
}

const getColumnDef = (columnHelper: ColumnHelper<RowData>, column: TableColumn<RowData>) =>
  columnHelper.accessor(column.key, {
    id: column.key as string,
    header: typeof column.title === 'function' ? /* istanbul ignore next */ () => column.title : column.title,
    cell: column.render ? () => column.render : (info) => info.getValue(),
    footer: typeof column.footer === 'function' ? /* istanbul ignore next */ () => column.footer : column.footer,
    sortingFn: column.sorter === true ? 'auto' : column.sorter || undefined,
    size: typeof column.width === 'number' ? column.width : undefined,
    minSize: column.minWidth,
    maxSize: column.maxWidth,
    meta: {
      align: column.align,
      colSpan: column.colSpan,
      actions: column.actions,
      getActions: memo(
        (header?: Header<RowData, unknown>) => [
          header?.column.getCanSort(),
          header?.column.getIsSorted(),
          header?.column.columnDef.meta?.actions,
        ],
        (canSort, isSorted, customActions = []) => {
          const sortActions = [];
          if (canSort) {
            sortActions.push(
              isSorted === 'asc'
                ? // Use an empty function for `prefix` to enable slot rendering
                  { value: 'clear-sort', label: 'Clear sort', prefix: noop }
                : { value: 'sort-ascending', label: 'Sort ascending', prefix: noop },
              isSorted === 'desc'
                ? { value: 'clear-sort', label: 'Clear sort', prefix: noop }
                : { value: 'sort-descending', label: 'Sort descending', prefix: noop },
            );
          }
          if (!sortActions.length && !customActions.length) {
            return [] as DropdownItem[];
          } else {
            return [sortActions.length && { value: 'sorting', children: sortActions }, ...customActions].filter(
              Boolean,
            ) as DropdownItem[];
          }
        },
        { key: 'TableHeadRow.getActions' },
      ),
    },
    enableSorting: Boolean(column.sorter),
  }) as ColumnDef<RowData, unknown>;
export const getTableColumnDefs = ({
  columns,
  options,
  rowSelection,
  expandable,
}: Pick<CreateTableInstanceProps, 'columns' | 'options' | 'rowSelection' | 'expandable'>) => {
  const columnHelper = createColumnHelper<RowData>();
  const columnDefs: ColumnDef<RowData, unknown>[] = columns.map((column) =>
    'columns' in column
      ? columnHelper.group({
          id: column.key,
          header: typeof column.title === 'function' ? /* istanbul ignore next */ () => column.title : column.title,
          columns: column.columns.map((column) => getColumnDef(columnHelper, column)),
        })
      : getColumnDef(columnHelper, column),
  );

  if (options.enableExpanding) {
    columnDefs.unshift(
      columnHelper.display({
        id: TOGGLER_COLUMN_ID,
        minSize: expandable?.columnWidth || TOGGLER_COLUMN_SIZE,
        size: expandable?.columnWidth || TOGGLER_COLUMN_SIZE,
        maxSize: expandable?.columnWidth || TOGGLER_COLUMN_SIZE,
        meta: { align: 'center' },
      }),
    );
  }

  if (options.enableRowSelection) {
    columnDefs.unshift(
      columnHelper.display({
        id: SELECTION_COLUMN_ID,
        minSize: rowSelection?.columnWidth || SELECTION_COLUMN_SIZE,
        size: rowSelection?.columnWidth || SELECTION_COLUMN_SIZE,
        maxSize: rowSelection?.columnWidth || SELECTION_COLUMN_SIZE,
        meta: { align: 'center' },
      }),
    );
  }

  return columnDefs;
};

export const createTableInstance = ({
  dataSource,
  columns,
  rowKey,
  getSubRows,
  options,
  state,
  rowSelection,
  expandable,
}: CreateTableInstanceProps) => {
  const columnDefs = getTableColumnDefs({ columns, options, rowSelection, expandable });

  logger?.debug('createTableInstance', {
    state,
    options,
    columnDefs,
    dataSource,
  });

  return createTable({
    state,
    onStateChange: noop,
    renderFallbackValue: null,
    data: dataSource,
    columns: columnDefs,
    getCoreRowModel: getCoreRowModel(),
    getRowId: rowKey,
    getSubRows,
    ...options,
  });
};
