import { Prop, State, Event, type EventEmitter, type MixinFactory } from '@stencil/core';
import { getPaginationRowModel, type PaginationState, type PaginationOptions } from '@byted-keystone/table';
import { DEFAULT_PAGE, DEFAULT_PAGE_SIZE, resolveUpdater } from '../helpers';
import type { TablePaginationConfig, TableFeatureArgs } from '../types';

const DEFAULT_PAGINATION_STATE = { pageIndex: DEFAULT_PAGE - 1, pageSize: DEFAULT_PAGE_SIZE };

export const PaginationFactory = (Base: ReturnType<MixinFactory>) => {
  class TablePagination extends Base {
    @State() internalPaginationState: PaginationState = DEFAULT_PAGINATION_STATE;

    /** Pagination configuration. Set to false to disable pagination. */
    @Prop() pagination?: TablePaginationConfig | false;

    /** Emitted when the pagination state changes. Emits the next page index and page size. */
    @Event({ bubbles: false, composed: false }) ksPaginationStateChange!: EventEmitter<PaginationState>;

    constructor() {
      super();
    }

    getPaginationState = (manual: boolean): PaginationState => {
      if (this.pagination === false) {
        return {
          pageIndex: 0,
          pageSize: Number.MAX_SAFE_INTEGER,
        };
      }
      return manual
        ? {
            pageIndex: (this.pagination?.page || DEFAULT_PAGE) - 1,
            pageSize: this.pagination?.pageSize || DEFAULT_PAGE_SIZE,
          }
        : this.internalPaginationState;
    };

    setInitialPaginationState = () => {
      const initialPaginationState: PaginationState =
        this.pagination !== false
          ? {
              // Tanstack table page index is 0-based, so we need to subtract 1
              pageIndex: (this.pagination?.page || DEFAULT_PAGE) - 1,
              pageSize: this.pagination?.pageSize || DEFAULT_PAGE_SIZE,
            }
          : {
              pageIndex: 0,
              pageSize: Number.MAX_SAFE_INTEGER,
            };

      this.internalPaginationState = initialPaginationState;
    };

    getPaginationFeatureOptions = ({ manual, updateTableOptions }: TableFeatureArgs): PaginationOptions =>
      this.pagination !== false
        ? {
            manualPagination: manual,
            rowCount: this.pagination?.total,
            getPaginationRowModel: getPaginationRowModel(),
            onPaginationChange: (updater) => {
              const newPaginationState = resolveUpdater(updater, this.getPaginationState(manual));
              if (!manual) {
                this.internalPaginationState = newPaginationState;
                updateTableOptions();
              }
              this.ksPaginationStateChange.emit(newPaginationState);
            },
          }
        : {
            getPaginationRowModel: getPaginationRowModel(),
          };
  }
  return TablePagination;
};
