import type { ColumnSizingState, ColumnDef, RowData } from '@byted-keystone/table';
import type { TableColumn, TableColumnGroup } from '../types';
import { getHiddenColumnKeys } from './column-visibility';
import { SELECTION_COLUMN_ID, TOGGLER_COLUMN_ID } from './constant';

const PERCENTAGE_DIVISOR = 100;

const flattenLeafColumns = <T>(columns: T[], getChildren: (column: T) => T[] | undefined): T[] =>
  columns.flatMap((column) => {
    const children = getChildren(column);
    return children?.length ? flattenLeafColumns(children, getChildren) : [column];
  });

export interface ResolveResponsiveColumnWidthsArgs {
  columnDefs: ColumnDef<RowData, unknown>[];
  columns: (TableColumn | TableColumnGroup)[];
  manualColumnSizes: ColumnSizingState;
  totalWidth: number;
}

export const resolveResponsiveColumnWidths = ({
  columnDefs,
  columns,
  manualColumnSizes,
  totalWidth,
}: ResolveResponsiveColumnWidthsArgs) => {
  const businessLeafColumns = flattenLeafColumns(columns, (column) =>
    'columns' in column ? column.columns : undefined,
  ).filter((column): column is TableColumn => !('columns' in column));
  const hiddenColumnIds = new Set(getHiddenColumnKeys(columns));
  const visibleBusinessLeafColumns = businessLeafColumns.filter((column) => !column.hidden);
  const generatedLeafColumnDefs = flattenLeafColumns(columnDefs, (columnDef) =>
    'columns' in columnDef ? (columnDef.columns as ColumnDef<RowData, unknown>[]) : undefined,
  ).filter(
    (columnDef) =>
      columnDef.id !== SELECTION_COLUMN_ID &&
      columnDef.id !== TOGGLER_COLUMN_ID &&
      (columnDef.id ? !hiddenColumnIds.has(columnDef.id) : true),
  );
  const generatedLeafColumnDefsById = new Map(
    generatedLeafColumnDefs.map((columnDef) => [columnDef.id, columnDef] as const),
  );

  const fixedBuiltInWidth = columnDefs
    .filter((columnDef) => columnDef.id === SELECTION_COLUMN_ID || columnDef.id === TOGGLER_COLUMN_ID)
    .reduce((sum, columnDef) => sum + (columnDef.size || 0), 0);

  let determinedSize = fixedBuiltInWidth;
  let resolvedPercentageWidth = false;

  for (const columnDef of generatedLeafColumnDefs) {
    if (!columnDef.id) continue;

    const manualSize = manualColumnSizes[columnDef.id];
    if (typeof manualSize === 'number') {
      columnDef.size = manualSize;
    }
    determinedSize += columnDef.size || 0;
  }

  for (const column of visibleBusinessLeafColumns) {
    const columnId = column.key as string;
    if (typeof manualColumnSizes[columnId] === 'number') {
      continue;
    }

    const columnWidth = column.width;
    if (typeof columnWidth !== 'string' || !columnWidth.endsWith('%')) {
      continue;
    }

    const matchedColumnDef = generatedLeafColumnDefsById.get(columnId);
    if (!matchedColumnDef) {
      continue;
    }

    determinedSize -= matchedColumnDef.size || 0;
    const percentageWidth = (totalWidth * Number.parseFloat(columnWidth)) / PERCENTAGE_DIVISOR;
    matchedColumnDef.size = percentageWidth;
    determinedSize += percentageWidth;
    resolvedPercentageWidth = true;
  }

  const columnsWithoutSize = generatedLeafColumnDefs.filter((columnDef) => !columnDef.size);
  const remainingWidth = totalWidth - determinedSize;
  const distributedRemainingWidth = columnsWithoutSize.length > 0 && remainingWidth > 0;
  if (distributedRemainingWidth) {
    const sizePerColumn = remainingWidth / columnsWithoutSize.length;
    columnsWithoutSize.forEach((columnDef) => (columnDef.size = sizePerColumn));
  }

  const resolvedColumnSizes = generatedLeafColumnDefs.reduce<Record<string, number>>((acc, columnDef) => {
    if (columnDef.id && typeof columnDef.size === 'number') {
      acc[columnDef.id] = columnDef.size;
    }
    return acc;
  }, {});

  return {
    resolvedColumnSizes,
    resolvedPercentageWidth,
    shouldDistributeRemainingWidth: distributedRemainingWidth,
  };
};
