import { h, type FunctionalComponent } from '@stencil/core';
import { SELECTION_COLUMN_ID, renderHeaderCell } from '../helpers';
import { TableSelectionCheckbox } from './table-selection-checkbox';
import type { JSXBase, VNode } from '@stencil/core/internal';
import type { Table, Header, RowData, SortDirection, HeaderContext } from '@byted-keystone/table';
import type { DropdownItem } from '@src/components';
import { TableResizableConfig, TableRowSelectionConfig } from '../types';
import { KsIconArrowDown, KsIconArrowUp, KsIconDragItem } from '@fe-infra/keystone-icons-stencil';

interface ITableHeadRowProps<TData> extends JSXBase.HTMLAttributes<HTMLTableRowElement> {
  prefix: string;
  table: Table<TData>;
  rowSelection?: TableRowSelectionConfig<TData>;
  draggable?: boolean;
  resizable?: boolean | TableResizableConfig;
  headers: Header<TData, unknown>[];
  virtual?: boolean;
  isLastPinned?: boolean;
  onAction?: (action: string, header: Header<TData, unknown>) => void;
  contentPartName?: string | ((headerContext: HeaderContext<TData, unknown>) => string);
  innerContentPartName?: string | ((headerContext: HeaderContext<TData, unknown>) => string);
  cellPartName?: string | ((headerContext: HeaderContext<TData, unknown>) => string);
  slotKey: (instance: Header<TData, unknown>) => string;
  wrapWithSlot: (slotName: string, children: unknown) => unknown;
  setDynamicRenderDeps: (headerId: string, children: unknown[], getPassThroughSlots?: () => VNode[]) => void;
  passThroughSlots: Record<string, VNode[]>;
}

// eslint-disable-next-line max-lines-per-function
export const TableHeadRow = <TData extends RowData>(props: ITableHeadRowProps<TData>): FunctionalComponent => {
  const {
    prefix,
    resizable,
    table,
    rowSelection,
    draggable,
    headers,
    virtual,
    isLastPinned,
    onAction,
    cellPartName,
    contentPartName,
    innerContentPartName,
    slotKey,
    wrapWithSlot,
    setDynamicRenderDeps,
    passThroughSlots,
    ...restProps
  } = props;

  const canSelectAll = rowSelection?.canSelectAll !== false;

  function handleToggleAllRowsSelected(checked: boolean) {
    if (!canSelectAll) return;
    table.toggleAllRowsSelected(checked);
  }

  const renderHeaderActions = (header: Header<TData, unknown>) => {
    // Only sort actions should be built-in supported

    const actions = header.column.columnDef.meta?.getActions?.(header as Header<RowData, unknown>);

    if (!actions?.length) {
      return null;
    }

    const handleClick = ({ detail: [value] }: CustomEvent<[string[], DropdownItem[]]>) => {
      switch (value[0]) {
        case 'clear-sort':
          header.column.clearSorting();
          break;
        case 'sort-ascending':
          header.column.toggleSorting(false);
          break;
        case 'sort-descending':
          header.column.toggleSorting(true);
          break;
        default:
      }

      onAction?.(value[0] || '', header);
    };

    return (
      <ks-dropdown-button
        class={`${prefix}__thead-cell-dropdown`}
        size="xs"
        variant="text"
        popupWidth="auto"
        options={actions}
        onKsChange={handleClick}
        setDynamicRenderDeps={(...params) => setDynamicRenderDeps(header.column.id, ...params)}
        wrapWithSlot={wrapWithSlot}
      >
        {passThroughSlots[header.column.id]}
      </ks-dropdown-button>
    );
  };

  const renderSortIndicator = (isSorted: false | SortDirection) => {
    if (isSorted === 'asc') return <KsIconArrowUp size="14" />;
    if (isSorted === 'desc') return <KsIconArrowDown size="14" />;
    return null;
  };

  const firstCenterHeaderIndex = virtual ? headers.findIndex((header) => !header.column.getIsPinned()) : -1;
  const lastCenterHeaderIndex = virtual
    ? headers.reduce((lastIndex, header, index) => (!header.column.getIsPinned() ? index : lastIndex), -1)
    : -1;

  return (
    <tr class={`${prefix}__thead-row`} {...restProps}>
      {headers.map((header, index) => {
        const columnAlign = header.column.columnDef.meta?.align;
        const columnPinningPosition = header.column.getIsPinned();
        const isLastLeftPinnedColumn = columnPinningPosition === 'left' && header.column.getIsLastColumn('left');
        const isFirstRightPinnedColumn = columnPinningPosition === 'right' && header.column.getIsFirstColumn('right');

        let widthStyle = virtual ? `calc(var(--ks-comp-width-table-column-${header.column.id}) * 1px)` : undefined;

        if (virtual && header.colSpan > 1) {
          const leafHeaders = header.getLeafHeaders();
          if (leafHeaders.length > 0) {
            const sumVar = leafHeaders.map((h) => `var(--ks-comp-width-table-column-${h.column.id})`).join(' + ');
            widthStyle = `calc((${sumVar}) * 1px)`;
          }
        }

        const isSorted = header.column.getIsSorted();
        const horizontalAlign = columnAlign === 'end' ? 'end' : 'start';

        return (
          <th
            key={header.id}
            colSpan={header.colSpan}
            class={{
              [`${prefix}__cell`]: true,
              [`${prefix}__thead-cell`]: true,
              [`${prefix}__cell--end-shadow`]: isLastLeftPinnedColumn,
              [`${prefix}__cell--start-shadow`]: isFirstRightPinnedColumn,
              [`${prefix}__cell--pinned`]: Boolean(columnPinningPosition),
              [`${prefix}__cell--last-pinned`]: Boolean(isLastPinned),
              [`${prefix}__cell--align-${columnAlign}`]: Boolean(columnAlign),
            }}
            style={{
              width: widthStyle,
              marginInlineStart:
                index === firstCenterHeaderIndex ? 'var(--ks-comp-table-virtual-padding-start)' : undefined,
              marginInlineEnd: index === lastCenterHeaderIndex ? 'var(--ks-comp-table-virtual-padding-end)' : undefined,
              insetInlineStart: columnPinningPosition === 'left' ? `${header.column.getStart('left')}px` : undefined,
              insetInlineEnd: columnPinningPosition === 'right' ? `${header.column.getAfter('right')}px` : undefined,
            }}
            data-column-id={header.column.id}
            part={typeof cellPartName === 'function' ? cellPartName(header.getContext()) : cellPartName}
            data-testid={`components-table-head-row-mGTbNn-${header.id}`}
          >
            <div
              class={`${prefix}__cell-content`}
              part={typeof contentPartName === 'function' ? contentPartName(header.getContext()) : contentPartName}
            >
              {header.column.id === SELECTION_COLUMN_ID &&
                (header.isPlaceholder ? null : (
                  <TableSelectionCheckbox
                    checked={table.getIsAllRowsSelected()}
                    indeterminate={!table.getIsAllRowsSelected() && table.getIsSomeRowsSelected()}
                    disabled={!canSelectAll}
                    onChange={handleToggleAllRowsSelected}
                    aria-label="Select all rows"
                    data-testid="components-table-head-row-srkg1f"
                  />
                ))}
              {header.column.id !== SELECTION_COLUMN_ID &&
                (header.isPlaceholder ? null : (
                  <div
                    class={{
                      [`${prefix}__cell-content--header`]: true,
                      [`${prefix}__cell-content--header--${horizontalAlign}`]: true,
                    }}
                    part={
                      typeof innerContentPartName === 'function'
                        ? innerContentPartName(header.getContext())
                        : innerContentPartName
                    }
                  >
                    {draggable && !columnPinningPosition && (
                      <KsIconDragItem
                        class={{
                          [`${prefix}__dragger`]: true,
                          [`${prefix}__dragger--${horizontalAlign}`]: true,
                        }}
                        size="12"
                      />
                    )}
                    <div
                      class={{
                        [`${prefix}__cell-content--header--content`]: true,
                      }}
                    >
                      {renderHeaderCell(header.column.columnDef.header, header.getContext(), slotKey)}
                      {renderSortIndicator(isSorted)}
                    </div>
                    {renderHeaderActions(header)}
                  </div>
                ))}

              {resizable && (
                <div
                  class={{
                    [`${prefix}__resizer`]: true,
                    [`${prefix}__resizer--active`]: header.column.getIsResizing(),
                  }}
                  onPointerDown={header.getResizeHandler()}
                  onTouchStart={header.getResizeHandler()}
                  data-testid="components-table-head-row-8upJrd"
                />
              )}
            </div>
          </th>
        );
      })}
    </tr>
  );
};
