import { State, Prop, Event, type EventEmitter, type MixinFactory } from '@stencil/core';
import { fill, zipObject } from 'lodash-es';
import { DetailArgs } from '@src/shared/dom';
import { resolveUpdater } from '../helpers';
import type { Row, RowSelectionOptions, RowData, RowSelectionState } from '@byted-keystone/table';
import type { TableFeatureArgs, TableRowSelectionConfig } from '../types';

export const SelectionFactory = (Base: ReturnType<MixinFactory>) => {
  class TableSelection extends Base {
    @State() internalRowSelectionState: RowSelectionState = {};

    /** Row selection configuration for single or multiple selection. */
    @Prop() rowSelection?: TableRowSelectionConfig;

    /** Emitted when the row selection state changes. Emits the selection state and selected rows. */
    @Event({ bubbles: false, composed: false }) ksRowSelectionStateChange!: EventEmitter<
      DetailArgs<[RowSelectionState, (Row<RowData> | null)[]]>
    >;

    constructor() {
      super();
    }

    assembleRowSelectionState = (selectedRowKeys: string[] = []): Record<string, boolean> =>
      zipObject(selectedRowKeys, fill(Array(selectedRowKeys.length), true));

    getRowSelectionState = (manual: boolean): RowSelectionState =>
      manual ? this.assembleRowSelectionState(this.rowSelection?.selectedRowKeys) : this.internalRowSelectionState;

    setInitialRowSelectionState = () => {
      const initialRowSelectionState: RowSelectionState = this.rowSelection
        ? this.assembleRowSelectionState(this.rowSelection.selectedRowKeys)
        : {};

      this.internalRowSelectionState = initialRowSelectionState;
    };

    getSelectionFeatureOptions = ({
      manual,
      getTableInstance,
      updateTableOptions,
    }: TableFeatureArgs): RowSelectionOptions<RowData> =>
      this.rowSelection
        ? {
            enableRowSelection: this.rowSelection.canSelectRow,
            onRowSelectionChange: (updater) => {
              const newRowSelectionState = resolveUpdater(updater, this.getRowSelectionState(manual));
              // TODO
              // newRowSelectionState = resolveSelectedRows(getTableInstance(), newRowSelectionState);
              if (!manual) {
                this.internalRowSelectionState = newRowSelectionState;
                updateTableOptions();
              }

              const table = getTableInstance();
              const selectedRows: (Row<RowData> | null)[] = manual
                ? Object.keys(newRowSelectionState).map((key) => {
                    try {
                      return table.getRow(key);
                    } catch (error) {
                      return null;
                    }
                  })
                : table.getSelectedRowModel().rows;
              this.ksRowSelectionStateChange.emit(DetailArgs(newRowSelectionState, selectedRows));
            },
          }
        : {};
  }
  return TableSelection;
};
