import type { RowData } from '@byted-keystone/table';
import type { TableColumn, TableColumnGroup } from '../types';

export const getHiddenColumnKeys = (columns: (TableColumn<RowData> | TableColumnGroup)[]) =>
  columns
    .flatMap((column) => ('columns' in column ? column.columns : column))
    .filter((column) => column.hidden)
    .map((column) => column.key);
